// @generated by:gauntlet run:godseye-local-agent-center
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type AgentsFixture, agentsFixture } from "./helpers/agents-fixture.js";

describe("owner-bound Hermes profile lifecycle", () => {
  let f: AgentsFixture;
  beforeEach(async () => {
    f = await agentsFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });

  it("T-AC-721 creates exact real scope and collapses identical idempotent creation", async () => {
    const key = randomUUID();
    const profile = await f.create({}, key);
    expect(await f.create({}, key)).toEqual(profile);
    expect(profile).toMatchObject({
      projectId: f.project.id,
      environmentId: f.development.id,
      role: "operations",
      model: "gpt-6-luna",
      paused: false,
      tools: [],
      skill: { id: "godseye-context", version: "1.0.0" },
    });
    await expect(f.create({ role: "security" }, key)).rejects.toMatchObject({
      code: "IDEMPOTENCY_CONFLICT",
    });
    expect((await f.infrastructure.agents.overview(f.freshOwner())).profiles).toHaveLength(1);
  });

  it("T-AC-721 denies services access to owner profile creation and overview", async () => {
    const service = { id: "fixture-service", kind: "service" as const, projectIds: [f.project.id] };
    await expect(
      f.infrastructure.agents.createProfile(service, f.profileInput, randomUUID()),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    await expect(f.infrastructure.agents.overview(service)).rejects.toMatchObject({
      code: "FORBIDDEN",
    });
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-722 refuses foreign environments and stale project or environment revisions", async () => {
    const foreign = f.secondProject.environments[0];
    if (!foreign) throw new Error("Missing independent fixture environment");
    await expect(f.create({ environmentId: foreign.id })).rejects.toMatchObject({
      code: "FORBIDDEN",
    });
    await expect(f.create({ expectedProjectRevision: 99 })).rejects.toMatchObject({
      code: "REVISION_CONFLICT",
    });
    await expect(f.create({ expectedEnvironmentRevision: 99 })).rejects.toMatchObject({
      code: "REVISION_CONFLICT",
    });
    expect((await f.infrastructure.agents.overview(f.freshOwner())).profiles).toHaveLength(0);
  });

  it("T-AC-722 refuses recovery-held scope before creating profile state", async () => {
    await f.store.db
      .update(schema.environments)
      .set({ recoveryHold: true })
      .where(eq(schema.environments.id, f.development.id));
    await expect(f.create()).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-722 refuses expired and suspended scopes before profile publication", async () => {
    await f.store.db
      .update(schema.environments)
      .set({ kind: "preview", expiresAt: new Date(f.clock.now().getTime() - 1) })
      .where(eq(schema.environments.id, f.development.id));
    await expect(f.create()).rejects.toMatchObject({ code: "ENVIRONMENT_EXPIRED" });
    await f.store.db
      .update(schema.environments)
      .set({ kind: "development", expiresAt: null })
      .where(eq(schema.environments.id, f.development.id));
    await f.store.db
      .update(schema.projects)
      .set({ status: "suspended" })
      .where(eq(schema.projects.id, f.project.id));
    await expect(f.create()).rejects.toMatchObject({ code: "PROJECT_SUSPENDED" });
    expect((await f.infrastructure.agents.overview(f.freshOwner())).profiles).toHaveLength(0);
  });

  it("T-AC-721 pauses and resumes using current profile revisions", async () => {
    const profile = await f.create();
    const paused = await f.infrastructure.agents.pause(
      f.freshOwner(),
      profile.id,
      { expectedRevision: profile.revision },
      randomUUID(),
    );
    expect(paused).toMatchObject({ paused: true, revision: profile.revision + 1 });
    await expect(
      f.infrastructure.agents.resume(
        f.freshOwner(),
        profile.id,
        { expectedRevision: profile.revision },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "REVISION_CONFLICT" });
    await expect(f.launch(profile.id, paused.revision)).rejects.toMatchObject({
      code: "AGENT_PROFILE_PAUSED",
    });
    const resumed = await f.infrastructure.agents.resume(
      f.freshOwner(),
      profile.id,
      { expectedRevision: paused.revision },
      randomUUID(),
    );
    expect(resumed).toMatchObject({ paused: false, revision: paused.revision + 1 });
  });

  it("T-AC-721 configures bounded policy with CAS without changing scope or role", async () => {
    const profile = await f.create();
    const input = {
      expectedRevision: profile.revision,
      expectedProjectRevision: f.project.revision,
      expectedEnvironmentRevision: f.development.revision,
      model: profile.model,
      limits: { ...profile.limits, maxOutputTokens: 256 },
    };
    const configured = await f.infrastructure.agents.configureProfile(
      f.freshOwner(),
      profile.id,
      input,
      randomUUID(),
    );
    expect(configured).toMatchObject({
      projectId: profile.projectId,
      environmentId: profile.environmentId,
      role: profile.role,
      revision: profile.revision + 1,
      limits: { maxOutputTokens: 256 },
    });
    await expect(
      f.infrastructure.agents.configureProfile(f.freshOwner(), profile.id, input, randomUUID()),
    ).rejects.toMatchObject({ code: "REVISION_CONFLICT" });
  });

  it("T-AC-724 keeps unconfigured runtime metadata honest and refuses launch", async () => {
    f.provider.admission = () => false;
    const profile = await f.create();
    expect(profile.runtime).toBe("unconfigured");
    await expect(f.launch(profile.id, profile.revision)).rejects.toMatchObject({
      code: "CAPABILITY_UNAVAILABLE",
    });
    expect(f.provider.submissions).toHaveLength(0);
    expect((await f.infrastructure.agents.overview(f.freshOwner())).tasks).toHaveLength(0);
  });
});
